update fs_grant_deadlines set status='submitted', next_step='Wells form submitted 11/1 (decision emailed within 30 days; Wells favors fundraisers, so a no is possible)', next_step_due='2026-12-01', notes = notes || ' FORM SUBMITTED 11/1/2026 (Benefit, product, 50/week; stated it is a free youth program, not a fundraiser).' where funder like 'Wells Enterprises%' and notes not like '%FORM SUBMITTED%';
update fs_grant_deadlines set status='submitted', next_step='Froneri/Dreyer''s contact form sent 11/1 (reply promised within 3 working days; consumer line 866-311-6351, dreyers@casupport.com is a call center, not giving)', next_step_due='2026-11-09', notes = notes || ' FORM SUBMITTED 11/1/2026 on dreyersgrandicecream.com/contact-us (Sales Enquiry; youth music mentorship partnership + 50 servings/week).' where funder in ('Haagen-Dazs / Froneri','Dreyer''s Grand Ice Cream (Edy''s, Drumstick, Outshine) / Froneri') and notes not like '%FORM SUBMITTED%';
